`default_nettype none
// system_stub : simulation/lint stand-in for the block-design wrapper
// (system_wrapper, generated by Vivado from tcl/create_bd.tcl). Ports follow
// the same build options as top.v. Never add this file to the Vivado project.
module system_wrapper (
`ifdef USE_PMOD
    inout  wire [7:0]  pmod_tri_io,
`endif
`ifdef USE_FAN_RTL
    output wire [31:0] fan_ctrl_o,
    input  wire [6:0]  fan_duty_i,
`else
    output wire [0:0]  fan_en_b,
`endif
`ifdef USE_IIC
    inout  wire        iic_scl_io,
    inout  wire        iic_sda_io,
    output wire [3:0]  cam_ctrl_o,
`endif
`ifdef USE_CAM
    input  wire                  mipi_cam_clk_p,
    input  wire                  mipi_cam_clk_n,
    input  wire [`CAM_LANES-1:0] mipi_cam_data_p,
    input  wire [`CAM_LANES-1:0] mipi_cam_data_n,
`endif
`ifdef USE_DP
    output wire [31:0] dp_ctrl_o,
    input  wire [15:0] dp_frames_i,
    output reg         vid_clk,
    output reg         vid_rst,
    input  wire [35:0] vid_pixel,
    input  wire        vid_hsync,
    input  wire        vid_vsync,
    input  wire        vid_de,
`endif
    output reg         pl_clk,
    output reg         pl_rst
);
    initial begin
        pl_clk = 1'b0;
        pl_rst = 1'b1;
        #100 pl_rst = 1'b0;
    end
    always #5 pl_clk = ~pl_clk;     // 100 MHz

`ifdef USE_IIC
    assign iic_scl_io = 1'bz;
    assign iic_sda_io = 1'bz;
    assign cam_ctrl_o = 4'd0;
`endif
`ifdef USE_DP
    assign dp_ctrl_o = 32'd2;
    initial begin
        vid_clk = 1'b0;
        vid_rst = 1'b1;
        #100 vid_rst = 1'b0;
    end
    always #6.734 vid_clk = ~vid_clk;   // 74.25 MHz
    wire unused_dp = &{1'b0, dp_frames_i, vid_pixel, vid_hsync, vid_vsync, vid_de};
`endif
`ifdef USE_CAM
    wire unused_cam = &{1'b0, mipi_cam_clk_p, mipi_cam_clk_n, mipi_cam_data_p, mipi_cam_data_n};
`endif
`ifdef USE_PMOD
    assign pmod_tri_io = 8'bzzzz_zzzz;
`endif
`ifdef USE_FAN_RTL
    assign fan_ctrl_o = 32'd0;
    wire unused_ok = &{1'b0, fan_duty_i};
`else
    assign fan_en_b = 1'b1;
`endif
endmodule
`default_nettype wire
